import {clamp} from './core.js';
const pent=[0,2,4,7,9,12,14,16,19];
const hz=n=>440*2**((n-69)/12);
function tone(ctx,out,freq,start,length,volume,type='sine'){const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(volume,start+.015);gain.gain.exponentialRampToValueAtTime(.0001,start+Math.max(.03,length));osc.connect(gain).connect(out);osc.start(start);osc.stop(start+length+.025);osc.onended=()=>{osc.disconnect();gain.disconnect()};}
export function scheduleDay(ctx,out,d,i,at,step,palette){const root=palette==='warm'?45:48;const color=d.color??.5;const note=root+12+pent[Math.round(clamp(color)*(pent.length-1))];const fullness=d.fullness??.5,tension=d.tension??0;const sustain=Math.max(.09,step*(.8+fullness*1.8));const type=palette==='warm'?'triangle':'sine';tone(ctx,out,hz(note),at,sustain,d.hasData?.07:.018,type);if(d.hasData){tone(ctx,out,hz(root+(Math.floor(i/28)%2?5:0)),at,Math.max(.15,step*2.5),.045);if(tension>.12)tone(ctx,out,hz(note+1),at+.01,Math.max(.08,step*.8),.03*tension);if(palette==='glass')tone(ctx,out,hz(note+12),at+.01,Math.max(.08,step*.6),.018);const pulses=Math.round((d.movement??0)*3);for(let p=0;p<pulses;p++)tone(ctx,out,100+(i%5)*30,at+p*step/3,Math.min(.055,step*.25),.024*(d.movement??0),'triangle');}}
export function outputBus(ctx){const gain=ctx.createGain(),comp=ctx.createDynamicsCompressor();gain.gain.value=.65;gain.connect(comp);comp.connect(ctx.destination);return gain;}
export function encodeWav(buffer){const samples=buffer.getChannelData(0),data=new ArrayBuffer(44+samples.length*2),view=new DataView(data);const str=(at,s)=>{for(let i=0;i<s.length;i++)view.setUint8(at+i,s.charCodeAt(i))};str(0,'RIFF');view.setUint32(4,36+samples.length*2,true);str(8,'WAVE');str(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,1,true);view.setUint32(24,buffer.sampleRate,true);view.setUint32(28,buffer.sampleRate*2,true);view.setUint16(32,2,true);view.setUint16(34,16,true);str(36,'data');view.setUint32(40,samples.length*2,true);for(let i=0;i<samples.length;i++){const n=clamp(samples[i],-1,1);view.setInt16(44+i*2,n<0?n*32768:n*32767,true)}return new Blob([data],{type:'audio/wav'});}
